function anionGap(na, cl, hco3){
  na=+na; cl=+cl; hco3=+hco3;
  if([na,cl,hco3].some(function(v){return isNaN(v);})) return {error:'Na / Cl / HCO3 三项均须为数字'};
  var ag=Math.round((na-(cl+hco3))*10)/10;
  var interp;
  if(ag>16) interp='升高 · 高阴离子间隙，提示代谢性酸中毒等可能';
  else if(ag<6) interp='降低 · 低阴离子间隙，注意实验室误差或低白蛋白等';
  else interp='正常范围（约 8–16）';
  return {ag:ag, interp:interp};
}
var EXPORTS={anionGap:anionGap};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AnionGapForgePure = EXPORTS; }
